DG=ref('CDC: Clinical Care of Dengue, 2026','https://www.cdc.gov/dengue/hcp/clinical-care/index.html')
DP=ref('CDC Dengue Clinical Management Pocket Guide','https://www.cdc.gov/dengue/hcp/pocketguide/index.html')
DT=ref('CDC: Clinical Testing Guidance for Dengue','https://www.cdc.gov/dengue/hcp/diagnosis-testing/')
